import { AfterViewInit, Component, ElementRef, HostListener, ViewChild } from '@angular/core';
import { BaseModalComponent } from '@app/layout/components/modal-components/base-modal/base-modal.component';
import { Session } from '@app/shared/interfaces/session';
import { Speaker } from '@app/shared/interfaces/speaker';

@Component({
  selector: 'app-session-modal',
  templateUrl: './session-modal.component.html',
})
export class SessionModalComponent extends BaseModalComponent implements AfterViewInit {
  session!: Session;
  speakers: Speaker[] = [];
  roomName = '';

  @ViewChild('closeButton') closeButton?: ElementRef<HTMLButtonElement>;

  ngAfterViewInit(): void {
    this.closeButton?.nativeElement.focus();
  }

  @HostListener('document:keydown.escape')
  onEscape(): void {
    this.close();
  }
}
