import { Component, OnDestroy, OnInit } from '@angular/core';
import { ActivatedRoute, Router } from '@angular/router';
import { appConfig } from '@app/app.config';
import { Subscription } from 'rxjs';

export type ScheduleView = 'glance' | 'detailed';

@Component({
  selector: 'app-schedule',
  templateUrl: './schedule.component.html',
})
export class ScheduleComponent implements OnInit, OnDestroy {
  constructor(
    private activatedRoute: ActivatedRoute,
    private router: Router,
  ) {
  }

  year = appConfig.year;
  showSchedule = appConfig.showSchedule;
  isBrowser = false;
  jsonFile: string = 'allSessionizeData.json';
  allSessionizeData: any;
  sessionGroups = {};
  view: ScheduleView = 'glance';

  private querySub?: Subscription;

  async ngOnInit() {
    this.querySub = this.activatedRoute.queryParamMap.subscribe(params => {
      this.view = params.get('view') === 'detailed' ? 'detailed' : 'glance';
    });

    this.allSessionizeData = await this.activatedRoute.snapshot.data["schedule"];
    this.sessionGroups = this.groupBy(this.allSessionizeData.sessions, 'startsAt')
  }

  ngOnDestroy(): void {
    this.querySub?.unsubscribe();
  }

  setView(view: ScheduleView): void {
    // Keep the choice in the URL so it survives refreshes and can be shared.
    this.router.navigate([], {
      relativeTo: this.activatedRoute,
      queryParams: { view: view === 'glance' ? null : view },
      replaceUrl: true,
    });
  }

  getRoomNameFromId(id:Number): string {
    const room: any = this.allSessionizeData.rooms.find( (o: any) => o.id === id);

    return room ? room.name : "";
  }

  // lacking built-in Object.groupBy()
  groupBy(items:[], key:string):object {
    return items.reduce(
      (result, item) => ({
        ...result,
        [item[key]]: [
          ...(result[item[key]] || []),
          item,
        ],
      }),
      {},
    );
  }
}
