import { isPlatformBrowser } from '@angular/common';
import {
  AfterViewInit,
  Component,
  ElementRef,
  Inject,
  Input,
  OnChanges,
  OnDestroy,
  OnInit,
  PLATFORM_ID,
  ViewChild,
} from '@angular/core';
import { BaseModalService } from '@app/core/services/base-modal.service';
import { Room } from '@app/shared/interfaces/room';
import { Session } from '@app/shared/interfaces/session';
import { Speaker } from '@app/shared/interfaces/speaker';
import { SessionModalComponent } from '../session-modal/session-modal.component';

export interface AgendaRoom {
  id: string;
  name: string;
  sponsor: string;
}

export interface AgendaCell {
  session: Session;
  roomName: string;
  speakers: Speaker[];
  speakerNames: string;
}

export interface AgendaSlot {
  startsAt: string;
  endsAt: string;
  // Breaks, lunch, registration, etc. render as a single full-width row.
  isServiceSlot: boolean;
  serviceLabel: string;
  serviceLocation: string;
  // One entry per talk room (in column order); null when the room is empty.
  cells: (AgendaCell | null)[];
}

function unique<T>(items: T[]): T[] {
  return [...new Set(items)];
}

@Component({
  selector: 'app-agenda-grid',
  templateUrl: './agenda-grid.component.html',
})
export class AgendaGridComponent implements OnInit, OnChanges, AfterViewInit, OnDestroy {
  constructor(
    @Inject(PLATFORM_ID) platformId: Object,
    private modalService: BaseModalService,
  ) {
    this.isBrowser = isPlatformBrowser(platformId);
  }

  @Input() data: any;

  @ViewChild('scroller') scroller?: ElementRef<HTMLElement>;

  isBrowser = false;
  rooms: AgendaRoom[] = [];
  slots: AgendaSlot[] = [];
  nowSlotStart: string | null = null;
  nextSlotStart: string | null = null;

  private timer?: ReturnType<typeof setInterval>;

  ngOnInit(): void {
    if (this.isBrowser) {
      this.timer = setInterval(() => this.updateNow(), 60 * 1000);
    }
  }

  ngOnChanges(): void {
    this.build();
    this.updateNow();
  }

  ngAfterViewInit(): void {
    if (this.isBrowser) {
      // Defer so the rendered rows exist before measuring.
      setTimeout(() => this.scrollToCurrent());
    }
  }

  ngOnDestroy(): void {
    if (this.timer) {
      clearInterval(this.timer);
    }
  }

  private build(): void {
    if (!this.data?.sessions) {
      this.rooms = [];
      this.slots = [];
      return;
    }

    const sessions: Session[] = this.data.sessions;
    const allRooms: Room[] = this.data.rooms ?? [];
    const speakers: Speaker[] = this.data.speakers ?? [];

    const talkRoomIds = new Set(
      sessions.filter(s => !s.isServiceSession).map(s => String(s.roomId))
    );

    this.rooms = allRooms
      .filter(r => talkRoomIds.has(String(r.id)))
      .sort((a, b) => (a.sort ?? 0) - (b.sort ?? 0))
      .map(r => {
        const [name, sponsor] = r.name.split('|').map(p => p.trim());
        return { id: String(r.id), name, sponsor: sponsor ?? '' };
      });

    const byStart = new Map<string, Session[]>();
    for (const s of sessions) {
      byStart.set(s.startsAt, [...(byStart.get(s.startsAt) ?? []), s]);
    }

    this.slots = [...byStart.keys()].sort().map(startsAt => {
      const group = byStart.get(startsAt)!;
      const endsAt = group.map(s => s.endsAt).sort().reverse()[0];
      const isServiceSlot = group.every(s => s.isServiceSession);

      return {
        startsAt,
        endsAt,
        isServiceSlot,
        serviceLabel: isServiceSlot ? unique(group.map(s => s.title)).join(' / ') : '',
        serviceLocation: isServiceSlot
          ? unique(group.map(s => this.roomName(allRooms, s.roomId))).join(', ')
          : '',
        cells: isServiceSlot
          ? []
          : this.rooms.map(room => {
              const session = group.find(s => String(s.roomId) === room.id);
              if (!session) {
                return null;
              }
              const sessionSpeakers = this.speakersFor(speakers, session);
              return {
                session,
                roomName: room.name,
                speakers: sessionSpeakers,
                speakerNames: sessionSpeakers
                  .map(sp => [sp.firstName, sp.lastName].filter(Boolean).join(' '))
                  .join(', '),
              };
            }),
      };
    });
  }

  private updateNow(): void {
    if (!this.isBrowser) {
      return;
    }

    // Sessionize times have no offset, so they parse as the viewer's local time.
    const now = Date.now();
    const current = this.slots.filter(
      s => Date.parse(s.startsAt) <= now && now < Date.parse(s.endsAt)
    );
    const upcoming = this.slots.find(s => Date.parse(s.startsAt) > now);

    // Prefer a talk slot over an overlapping service slot (e.g. welcome vs. break).
    this.nowSlotStart =
      (current.find(s => !s.isServiceSlot) ?? current[current.length - 1])?.startsAt ?? null;
    this.nextSlotStart = upcoming?.startsAt ?? null;
  }

  openSession(cell: AgendaCell): void {
    const modalRef = this.modalService.open(SessionModalComponent);
    modalRef.instance.session = cell.session;
    modalRef.instance.speakers = cell.speakers;
    modalRef.instance.roomName = cell.roomName;
  }

  private scrollToCurrent(): void {
    const container = this.scroller?.nativeElement;
    const gridVisible = !!container && container.offsetParent !== null;

    if (gridVisible) {
      // Wide grid: scroll inside its own box so the page itself doesn't jump.
      const target = this.nowSlotStart ?? this.nextSlotStart;
      const row = target && container!.querySelector<HTMLElement>(`[data-slot="${target}"]`);
      const header = container!.querySelector<HTMLElement>('thead');
      if (row) {
        container!.scrollTop = row.offsetTop - (header?.offsetHeight ?? 0);
      }
      return;
    }

    // Stacked list scrolls with the page, so only jump there while the event is live.
    if (this.nowSlotStart) {
      const item = document.querySelector<HTMLElement>(`[data-slot-stacked="${this.nowSlotStart}"]`);
      if (item) {
        const fixedHeaderHeight = 80;
        window.scrollTo({ top: item.getBoundingClientRect().top + window.scrollY - fixedHeaderHeight });
      }
    }
  }

  private roomName(rooms: Room[], id: string | number): string {
    const room = rooms.find(r => String(r.id) === String(id));
    return room ? room.name.split('|')[0].trim() : '';
  }

  private speakersFor(speakers: Speaker[], session: Session): Speaker[] {
    return session.speakers
      .map(id => speakers.find(sp => sp.id === id))
      .filter((sp): sp is Speaker => !!sp);
  }

  trackBySlot(_: number, slot: AgendaSlot): string {
    return slot.startsAt;
  }
}
